INSERT INTO training.task_tests VALUES ('security',6,4,'Readonly-роль не может изменять staging.orders','SELECT to_jsonb(NOT has_table_privilege(''training_readonly'',''staging.orders'',''INSERT''))','SELECT ''true''::jsonb');
